//! 🧪️ Every original partial native field prefix retains one final frame through paid publication or closure.
use super::*;
use pack::record::RetainedRecordBodySourceDecode;
use semio_framework_value::RetainedCloneGrant;
use semio_framework_value::RetainedCloneProgress;
use semio_framework_value_persistent::list::PagedList;
use std::mem::size_of;
use protocol::codec::{OriginalWireSourceIdentity,RetainedWireByteSource};
type Receipt=Option<(RetainedCloneGrant,RetainedCloneProgress)>;
fn original(source:&RetainedRecordBodySourceDecode)->(usize,usize,Option<(u64,u64)>,(usize,usize)){let s=source.source_identity();(s.address,s.extent,s.authority,source.original_range())}
struct Pages<'a>{bytes:&'a[u8]}
impl RetainedWireByteSource for Pages<'_>{fn original_source_identity(&self)->OriginalWireSourceIdentity{OriginalWireSourceIdentity{range_start:0,address:self.bytes.as_ptr()as usize,extent:self.bytes.len(),authority:Some((42,7))}}fn byte_at(&self,index:usize)->Option<u8>{self.bytes.chunks(7).nth(index/7)?.get(index%7).copied()}}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(v,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(v,(h.requested_bytes,h.released_bytes))}
fn receive(g:RetainedCloneGrant,p:RetainedCloneProgress,receipt:Receipt,heap:(usize,usize)){assert_eq!(receipt,Some((g,p)));assert!(p.fits(g));assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap)}
fn identity(source:&Pages<'_>,g:RetainedCloneGrant)->(RetainedRecordBodySourceDecode,ToolRunIdentityReceiving,(usize,usize)){
 let(mut lower,mut physical)=observe(||RetainedRecordBodySourceDecode::admit(source,(0,source.bytes.len()),ToolRunReceivingLimits::REPORTS.tick.record_body(),g).unwrap().unwrap());lower.take_receipt().unwrap();let(mut typed,_)=ToolRunIdentityReceiving::admit(&lower,g).unwrap();typed.take_receipt().unwrap();let mut pending=None;
 for _ in 0..10000{if typed.identity().is_some(){return(lower,typed,physical)}if lower.token().is_some(){assert!(lower.take_token_into(&mut pending,g).unwrap());lower.take_receipt().unwrap();}if pending.is_some(){if !matches!(pending,Some(pack::record::RetainedRecordBodyToken::Value(_))){pending=None;continue}let p=typed.receive(&lower,&mut pending,g).unwrap().unwrap();receive(g,p,typed.take_receipt(),(0,0));continue}let(_,h)=observe(||lower.step(source,g).unwrap());let receipt=lower.take_receipt().unwrap();receive(g,receipt.1,Some(receipt),h);physical.0+=h.0;physical.1+=h.1}panic!("original typed identity did not terminate")
}
#[test]
fn original_native_tick_preparation_preserves_final_frame_and_every_initialized_prefix(){
 let fixture:serde_json::Value=serde_json::from_str(crate::fixture_text("🎞️tick/🛬️receive/🏗️native/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let leaf:serde_json::Value=serde_json::from_str(crate::fixture_text("🎞️tick/🛬️receive/🪪️identity/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let bytes:Vec<u8>=leaf["bodyHex"].as_str().unwrap().as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect();let source=Pages{bytes:&bytes};
 let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:17,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let m=RetainedCloneGrant{maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,..g};
 for cut in fixture["interruptAfter"].as_array().unwrap(){let cut=cut.as_u64().unwrap()as usize;let(mut lower,mut typed,mut physical)=identity(&source,g);let expected=*typed.identity().unwrap();let mut limited=ToolRunReceivingLimits::REPORTS;limited.tick.maximum_total_allocation_bytes=1;limited.tick.maximum_cursor_allocation_bytes=1;let(denied,h)=observe(||ToolRunNativeTickPreparation::admit(&lower,limited,g));assert!(denied.is_err());assert_eq!(h,(0,0));drop(denied);
  for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:1,..g},RetainedCloneGrant{maximum_capacity_bytes:ToolRunNativeTickPreparation::birth_bytes()-1,..g}]{let(r,h)=observe(||ToolRunNativeTickPreparation::admit(&lower,ToolRunReceivingLimits::REPORTS,denied).unwrap());assert!(r.is_none());assert_eq!(h,(0,0))}
  let((mut preparation,p),h)=observe(||ToolRunNativeTickPreparation::admit(&lower,ToolRunReceivingLimits::REPORTS,g).unwrap().unwrap());receive(g,p,preparation.take_receipt(),h);physical.0+=h.0;physical.1+=h.1;let address=preparation.native_address().unwrap();let(mut accepted,mut copied,mut published)=(0,0,None);let mut sequence=Some(fixture["sequence"].as_u64().unwrap());
  while accepted<cut&&accepted<47{let(p,h)=observe(||if accepted<9{preparation.initialize_header_step(m).unwrap()}else if accepted<45{let quote=preparation.identity_demands();if quote.copy_bytes>0{assert!(preparation.receive_identity_step(&mut typed,m).unwrap().is_none());assert!(preparation.receipt().is_none())}preparation.receive_identity_step(&mut typed,g).unwrap().unwrap()}else if accepted==45{preparation.receive_sequence(&mut sequence,g).unwrap()}else{assert!(preparation.publish_into(&mut published,RetainedCloneGrant{maximum_items:0,..m}).is_none());preparation.publish_into(&mut published,m).unwrap()});let issued=if accepted<9||accepted==46{m}else{g};let receipt=if accepted==46{assert!(preparation.receipt().is_none());let native=published.as_mut().unwrap();assert!(native.tick().is_none());assert!(native.close_step(g).is_none());native.take_receipt()}else{preparation.take_receipt()};receive(issued,p,receipt,h);assert_eq!(h,(0,0));copied+=p.copied_bytes;accepted+=1;
   if published.is_none(){assert_eq!(preparation.native_address(),Some(address))}else{assert!(preparation.terminal_is_empty());let native=published.as_ref().unwrap();assert_eq!(native.native_address(),Some(address));assert_eq!(native.source_identity(),original(&lower));assert_eq!(native.limits(),&ToolRunReceivingLimits::REPORTS);let tick=native.tick().unwrap();assert_eq!(tick.identity(),&expected);assert_eq!(tick.sequence(),fixture["sequence"].as_u64().unwrap());assert!(tick.steps().is_empty()&&tick.trace().is_empty()&&tick.append_ops().is_empty()&&tick.append_entities().is_empty());assert_eq!(copied,56)}
  }
  if let Some(native)=published.as_mut(){native.cancel();while !native.terminal_is_empty(){let demand=native.close_demands();if demand.release_bytes>0{let(denied,h)=observe(||native.close_step(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..g}));assert!(denied.is_none());assert_eq!(h,(0,0));assert_eq!(native.native_address(),Some(address))}let(p,h)=observe(||native.close_step(g).unwrap());receive(g,p,native.take_receipt(),h);physical.0+=h.0;physical.1+=h.1}let(_,h)=observe(||drop(published.take()));assert_eq!(h,(0,0))}else{preparation.cancel();while !preparation.terminal_is_empty(){let demand=preparation.close_demands();if demand.release_bytes>0{let(denied,h)=observe(||preparation.close_step(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..g}));assert!(denied.is_none());assert_eq!(h,(0,0));assert_eq!(preparation.native_address(),Some(address))}let(p,h)=observe(||preparation.close_step(g).unwrap());receive(g,p,preparation.take_receipt(),h);physical.0+=h.0;physical.1+=h.1}}
  typed.cancel();let(p,h)=observe(||typed.close_step(m).unwrap());receive(m,p,typed.take_receipt(),h);lower.cancel();let mut pending=None;while !lower.terminal_is_empty(){if lower.token().is_some(){assert!(lower.take_token_into(&mut pending,g).unwrap());lower.take_receipt().unwrap();pending=None;}let(_,h)=observe(||lower.close_step(g).unwrap());let receipt=lower.take_receipt().unwrap();receive(g,receipt.1,Some(receipt),h);physical.0+=h.0;physical.1+=h.1}
  assert_eq!(physical.0,physical.1);let(_,h)=observe(||{drop(preparation);drop(typed);drop(lower)});assert_eq!(h,(0,0));
 }
}
#[test]
fn original_native_trace_column_reservation_keeps_all4096_ops_without_payload_moves(){
 let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:17,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let mut column=PagedList::<ToolRunTraceOp,4096>::empty();let mut pointers=Vec::with_capacity(4096);let mut born=0;
 for key in 0..4096{while !column.has_reserved_slot(){let bytes=column.next_allocation_bytes().unwrap();assert!(bytes<=g.maximum_capacity_bytes);assert!(column.next_reserve_depth_demand().unwrap()<=g.maximum_depth);assert_eq!(column.next_reserve_copy_byte_demand().unwrap(),0);let(p,h)=observe(||column.reserve_one_funded(RetainedCloneGrant{maximum_copy_bytes:0,..g}).unwrap());assert!(p.fits(g));assert_eq!(p.copied_bytes,0);assert_eq!(h,(p.retained_capacity_bytes,0));assert_eq!(p.retained_capacity_bytes,bytes);born+=h.0;for(index,pointer)in pointers.iter().enumerate(){assert_eq!(column.backing_ptr(index),Some(*pointer));}}
  let mut incoming=Some(ToolRunTraceOp::Upsert{key,verdict:crate::ToolRunVerdict::Success,reason:0,subject:crate::ToolRunTraceSubject::Instance3d{mesh:0,position:[0.;3],rotation:[0.;4],scale:1.}});let(p,h)=observe(||column.adopt_reserved(&mut incoming).unwrap());assert!(p.progressed);assert_eq!(p.placed_bytes,0);assert_eq!(h,(0,0));assert!(incoming.is_none());pointers.push(column.backing_ptr(column.len()-1).unwrap());
 }
 assert_eq!(column.len(),crate::TOOL_RUN_TRACE_PAGE_OPS_MAX);for(index,pointer)in pointers.iter().enumerate(){assert_eq!(column.backing_ptr(index),Some(*pointer));assert!(matches!(&column[index],ToolRunTraceOp::Upsert{key,..}if *key==index as u64))}while !column.is_empty(){assert!(column.next_pop_depth_demand().unwrap()<=g.maximum_depth);let(_,h)=observe(||column.truncate_retired_last().unwrap());assert_eq!(h,(0,0))}let mut released=0;while !column.terminal_is_empty(){assert!(column.next_release_depth_demand().unwrap()<=g.maximum_depth);let(p,h)=observe(||column.release_empty_page(g.maximum_release_bytes).unwrap());assert!(p.progressed);assert_eq!(h,(0,p.released_allocation_bytes));assert!(RetainedCloneProgress{copied_items:1,released_bytes:p.released_allocation_bytes,..Default::default()}.fits(g));released+=h.1}assert_eq!(born,released);let(_,h)=observe(||drop(column));assert_eq!(h,(0,0));
}
